<?php declare(strict_types=1);$base=config('app.base_path');$isTrash=!empty($trash);?><div class="page-header"><div><h1><?= $isTrash?'Deleted Modifier Groups':'Modifier Groups' ?></h1><p><?= $isTrash?'Restore modifier groups from Trash.':'Choices and add-ons such as spice levels, toppings and extras.' ?></p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?=$base?>/restaurant/modifiers">Active Groups</a><?php else: ?><a class="btn btn-secondary" href="<?=$base?>/restaurant/modifiers?view=trash">Trash</a><a class="btn btn-primary" href="<?=$base?>/restaurant/modifiers/create">Add Modifier Group</a><?php endif; ?></div></div><div class="card"><table class="table"><thead><tr><th>Restaurant</th><th>Group</th><th>Selection</th><th>Options</th><th>Required</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($groups)):?><tr><td colspan="7"><div class="empty-state"><?= $isTrash?'Trash is empty.':'No modifier groups found.' ?></div></td></tr><?php else:foreach($groups as $g):?><tr><td><?=htmlspecialchars((string)$g['restaurant_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars((string)$g['name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars((string)$g['selection_type'],ENT_QUOTES,'UTF-8')?></td><td><?= (int)$g['option_count']?></td><td><?=!empty($g['is_required'])?'Yes':'No'?></td><td><?=htmlspecialchars((string)$g['status'],ENT_QUOTES,'UTF-8')?></td><td><?php if($isTrash): ?><form method="post" action="<?=$base?>/restaurant/modifiers/<?= (int)$g['id']?>/restore"><button class="btn btn-secondary" type="submit">Restore</button></form><?php else: ?><a class="link-button" href="<?=$base?>/restaurant/modifiers/<?= (int)$g['id']?>">Manage</a> <a class="link-button" href="<?=$base?>/restaurant/modifiers/<?= (int)$g['id']?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach;endif;?></tbody></table></div>
